/**
 * `pnpm games:generate` (docs/spec/02-game-framework.md §7.3): writes the server registry, the
 * client import map and `installed.json` into `generated/`. Never edited by hand; git-ignored.
 */
import { mkdirSync, writeFileSync } from "node:fs";
import { join } from "node:path";

import type { LoadedGame } from "./load.js";

export type GeneratedFiles = Readonly<
  Record<"server-registry.ts" | "client-games.ts" | "installed.json", string>
>;

const HEADER =
  "// Generated by `pnpm games:generate` from instance.config.ts. Do not edit; not committed.\n";

const literal = (value: string): string => JSON.stringify(value);

/** The server registry: every installed package's manifest and engines (02 §7.3). */
function renderServerRegistry(games: readonly LoadedGame[]): string {
  const imports = games.flatMap((game, index) => [
    `import { engines as engines${String(index)} } from ${literal(`${game.packageName}/engine`)};`,
    `import { manifest as manifest${String(index)} } from ${literal(`${game.packageName}/manifest`)};`,
  ]);
  const entries = games.map(
    (game, index) =>
      `  { manifest: manifest${String(index)}, engines: engines${String(index)}, enabledByDefault: ${String(game.enabledByDefault)} },`,
  );
  return [
    HEADER,
    ...imports,
    ...(imports.length > 0 ? [""] : []),
    "/** Installed game packages, injected into `createApp` by each runtime. */",
    entries.length > 0
      ? `export const installedGames = [\n${entries.join("\n")}\n] as const;`
      : "export const installedGames = [] as const;",
    "",
  ].join("\n");
}

/** The client import map: each type's client module, loaded lazily (02 §7.3). */
function renderClientImports(games: readonly LoadedGame[]): string {
  const entries = games.map(
    (game) =>
      `  ${literal(game.manifest.type)}: () => import(${literal(`${game.packageName}/client`)}),`,
  );
  return [
    HEADER,
    "/** Game type → lazy import of its client module. */",
    `export const gameClients: Readonly<Record<string, () => Promise<unknown>>> = {${
      entries.length > 0 ? `\n${entries.join("\n")}\n` : ""
    }};`,
    "",
  ].join("\n");
}

/**
 * Plain data for deploy-time and startup orphan checks, which must never load package code:
 * game type → package and exported rules versions.
 */
function renderInstalled(games: readonly LoadedGame[]): string {
  const installed = Object.fromEntries(
    games.map((game) => [
      game.manifest.type,
      {
        package: game.packageName,
        version: game.pkg.version,
        rulesVersions: game.rulesVersions,
        enabledByDefault: game.enabledByDefault,
      },
    ]),
  );
  return `${JSON.stringify(installed, null, 2)}\n`;
}

export function renderAll(games: readonly LoadedGame[]): GeneratedFiles {
  return {
    "server-registry.ts": renderServerRegistry(games),
    "client-games.ts": renderClientImports(games),
    "installed.json": renderInstalled(games),
  };
}

export function writeGenerated(outDir: string, files: GeneratedFiles): void {
  mkdirSync(outDir, { recursive: true });
  for (const [name, content] of Object.entries(files)) {
    writeFileSync(join(outDir, name), content);
  }
}
